/* From Uiverse.io by Rodrypaladin - Tags: animation, purple, pink, card, hover, html, css, cool card */
.__UIV_SCOPE__ .card {
  width: 300px;
  padding: 10px;
  background-image: linear-gradient(to right bottom, #5d0391, #7b05ae, #9b05cb, #bd00e7, #bd00e7);
  background-size: 200% 200%;
  border-radius: 12px;
}

.__UIV_SCOPE__ .card-int {
  position: relative;
  height: 100%;
  overflow: hidden;
  font-size: 14px;
  border-radius: 6px;
  background-color: white;
}

.__UIV_SCOPE__ .img {
  width: 100%;
  height: 175px;
  background-color: pink;
}

.__UIV_SCOPE__ .title {
  font-weight: bold;
  font-size: 16px;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .card-data {
  padding: 20px;
  font-size: 14px;
}

.__UIV_SCOPE__ .card__span {
  font-family: 'Lucida Sans' sans-serif;
  font-size: 11px;
  position: absolute;
  top: 10px;
  left: 10px;
  background-color: white;
  padding: 5px 10px;
  border-radius: 15px;
}

.__UIV_SCOPE__ button {
  width: 100%;
  margin-top: 15px;
  background-image: linear-gradient(to right bottom, #5d0391, #7b05ae, #9b05cb, #bd00e7, #bd00e7);
  background-size: 200% 200%;
  border: none;
  padding: 8px 10px;
  color: white;
  font-size: 14px;
  font-weight: bold;
  border-radius: 5px;
  transition: transform 0.1s ease-in;
}

.__UIV_SCOPE__ button:active {
  transform: translateY(3px);
}

.__UIV_SCOPE__ .card:hover, .__UIV_SCOPE__ button:hover {
  animation: gradient 0.8s ease-in 1;
}

@keyframes gradient {
  0% {
    background-position: 200% 200%;
  }

  100% {
    background-position: 400% 400%;
  }
}
